using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using MyFundex.BuildingBlocks.Abstractions;using MyFundex.BuildingBlocks.Domain;using MyFundex.BuildingBlocks.Persistence;
namespace MyFundex.MarketData;
public sealed class Instrument:EntityBase{public Guid InstrumentId{get;set;}public string InstrumentToken{get;set;}="";public string ExchangeCode{get;set;}="NSE";public string Symbol{get;set;}="";public string TradingSymbol{get;set;}="";public string? Isin{get;set;}public string Name{get;set;}="";public string SecurityType{get;set;}="EQUITY";public decimal TickSize{get;set;}public int LotSize{get;set;}=1;public bool IsActive{get;set;}=true;}
public sealed class TradingCalendarDay:EntityBase{public Guid CalendarDayId{get;set;}public DateOnly TradeDate{get;set;}public string ExchangeCode{get;set;}="NSE";public bool IsTradingDay{get;set;}public TimeOnly? SessionOpen{get;set;}public TimeOnly? SessionClose{get;set;}public string? HolidayName{get;set;}}
public sealed class MarketDataDbContext(DbContextOptions<MarketDataDbContext>o,ICurrentActor a):AuditableDbContext(o,a){public DbSet<Instrument>Instruments=>Set<Instrument>();public DbSet<TradingCalendarDay>TradingCalendar=>Set<TradingCalendarDay>();protected override void OnModelCreating(ModelBuilder m) => ConfigureModel(m); public static void ConfigureModel(ModelBuilder m) {m.HasDefaultSchema("market");ConfigureEntity(m.Entity<Instrument>());ConfigureEntity(m.Entity<TradingCalendarDay>());m.Entity<Instrument>().HasIndex(x=>x.InstrumentId).IsUnique();m.Entity<Instrument>().HasIndex(x=>x.InstrumentToken).IsUnique().HasFilter("\"IsDeleted\" = false");m.Entity<Instrument>().HasIndex(x=>x.TradingSymbol);m.Entity<TradingCalendarDay>().HasIndex(x=>new{x.ExchangeCode,x.TradeDate}).IsUnique().HasFilter("\"IsDeleted\" = false");}}
public static class MarketDataModule{public static IServiceCollection AddMarketDataModule(this IServiceCollection s,string cs){s.AddDbContext<MarketDataDbContext>(o=>o.UseNpgsql(cs));return s;}}
